/* Development effects driver for one independently sourced genuine frame. */
#include "panda-policy.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static void need(int yes,const char*why){if(!yes){fprintf(stderr,"%s\n",why);exit(1);}}
static void read_exact(const char*root,const char*name,void*out,size_t bytes){char path[4096];snprintf(path,sizeof path,"%s/%s",root,name);FILE*f=fopen(path,"rb");need(f!=NULL,"input missing");need(fread(out,1,bytes,f)==bytes&&fgetc(f)==EOF,"input extent");need(!fclose(f),"input close");}
static void dump(PandaPolicy*p,const char*root,const char*name,size_t bytes){char path[4096];void*data=malloc(bytes);need(data!=NULL,"diagnostic allocation");need(panda_policy_copy(p,name,data,bytes),"diagnostic refused");snprintf(path,sizeof path,"%s/%s.bin",root,name);FILE*f=fopen(path,"wb");need(f!=NULL,"diagnostic create");need(fwrite(data,1,bytes,f)==bytes&&!fclose(f),"diagnostic write");free(data);}
int main(int argc,char**argv){need(argc==12,"usage: policy-frame SHARDS PST INPUTDIR OUTPUTDIR tile device vision wide text action INSTRUCTION");PandaPolicyConfig config={.shard_directory=argv[1],.pst_path=argv[2],.instruction=argv[11]};for(int i=0;i<6;i++)config.metal_paths[i]=argv[5+i];PandaPolicy*p=NULL;char error[512];need(panda_policy_open(&config,&p,error,sizeof error),error);printf("resident policy opened\n");fflush(stdout);
 unsigned char*agent=malloc(196608),*wrist=malloc(196608);float physical[8],noise[5280],decoded[112];need(agent&&wrist,"frame allocation");read_exact(argv[3],"agentview.rgb",agent,196608);read_exact(argv[3],"wrist.rgb",wrist,196608);read_exact(argv[3],"physical.f32",physical,sizeof physical);read_exact(argv[3],"noise.f32",noise,sizeof noise);need(panda_policy_capture(p,argv[4]),"capture setup");PandaPolicyTiming timing;need(panda_policy_forward(p,agent,wrist,physical,noise,decoded,&timing),panda_policy_error(p));
 dump(p,argv[4],"pixels",3145728);dump(p,argv[4],"state",528);dump(p,argv[4],"noise",21120);dump(p,argv[4],"ids",(size_t)timing.tokens*8);dump(p,argv[4],"backbone",(size_t)timing.tokens*8192);dump(p,argv[4],"normalized-actions",21120);dump(p,argv[4],"decoded-actions",448);
 printf("{\"tokens\":%lld,\"launches\":%lld,\"prep_seconds\":%.12g,\"vision_gpu_seconds\":%.12g,\"text_gpu_seconds\":%.12g,\"action_gpu_seconds\":%.12g,\"wall_seconds\":%.12g}\n",(long long)timing.tokens,(long long)timing.launches,timing.preparation_seconds,timing.vision_gpu_seconds,timing.text_gpu_seconds,timing.action_gpu_seconds,timing.total_seconds);panda_policy_close(p);free(agent);free(wrist);return 0;}
